using System.Text.Json.Nodes;
namespace Deadlock.Api.Ingestion;

internal static class EditorialAdvice
{
    public static JsonObject Read() => (JsonObject)JsonNode.Parse(
"""
{"Return Fire":[{"ru":"Полезен, когда враги продолжают наносить тебе урон в открытой перестрелке. Включай под ожидаемый фокус: ответные пули наказывают тех, кто атакует тебя оружием или способностями.","en":"Useful when enemies keep damaging you during an open fight. Activate before you are focused: retaliatory bullets punish attackers who hit you with weapons or abilities."}],"Arctic Blast":[{"ru":"Улучшай Cold Front для драки рядом с несколькими врагами: большая ледяная волна сначала замораживает цели, затем замедляет их и останавливает восстановление выносливости на время замедления. Это даёт команде окно для атаки и затрудняет последующий отход врагов.","en":"Upgrade Cold Front for fights near several enemies: the larger ice blast freezes targets, then slows them and stops their stamina regeneration while slowed. This gives your team an attack window and makes the enemies' follow-up retreat harder."}],"Greater Expansion":[{"ru":"Расширяет возможности атаки, когда дальности или радиуса не хватает сразу нескольким умениям и предметам: с ним можно начинать атаку дальше от врага и накрывать больше целей. Это развитие Mystic Expansion для набора с несколькими важными эффектами по области.","en":"Useful when several abilities and items need more reach or radius: you can start attacks from farther away and cover more targets. This develops Mystic Expansion for a kit with several important area effects."}],"Alchemical Fire":[{"ru":"Удержание врагов в горящей области позволяет нарастить спиритический урон и воспользоваться снижением сопротивления пулям для последующей стрельбы. Против существ, не являющихся героями, эффект слабее.","en":"Keeping enemies in the burning area lets the spirit damage ramp up and allows follow-up gunfire to benefit from reduced bullet resistance. It is less effective against non-heroes."}],"Rescue Beam":[{"ru":"Для спасения союзника, которого фокусят или отрезали от команды: во время лечения можно подтянуть его к себе. Занимай позицию, из которой притягивание действительно выводит его из опасности.","en":"For saving an ally who is being focused or cut off from the team: you can pull them to you while healing. Position yourself so that the pull actually takes them away from danger."}],"High-Velocity Rounds":[{"ru":"Если по движущемуся врагу трудно попасть из-за времени полёта пуль, увеличение их скорости уменьшит необходимое упреждение. Предмет также добавляет урон оружия.","en":"When bullet travel time makes moving enemies hard to hit, higher velocity reduces the lead you need. The item also adds weapon damage."}],"Fleetfoot":[{"ru":"Убирает штраф передвижения при стрельбе, если именно он мешает удерживать нужную дистанцию. Для погони или отхода активация дополнительно даёт скорость и сопротивление замедлению.","en":"Removes the movement penalty while firing when that penalty stops you from maintaining distance. Activation adds movement speed and slow resistance for chasing or retreating."}],"Rebuttal":[{"ru":"Против героя, который часто бьёт в ближнем бою, успешное парирование одновременно лечит тебя и возвращает ему урон. Используй полученное усиление для ответной атаки.","en":"Against a hero who relies on melee, a successful parry both heals you and returns damage to them. Use the resulting damage buff to counterattack."}],"Crippling Headshot":[{"ru":"Против цели с сильным лечением попадание в голову снижает входящее лечение и сопротивление пулям и спиритическому урону. Помогает команде добить врага совместной атакой оружием и способностями.","en":"Against a target receiving heavy healing, a headshot reduces incoming healing and both bullet and spirit resistance. This helps your team finish them with combined gunfire and abilities."}],"Trophy Collector":[{"ru":"Для активной игры с частыми убийствами и ассистами: участие в них постепенно усиливает бег, дальность способностей и доход душ. При этом предмет уменьшает урон оружия по неигровым целям.","en":"For active play with frequent kills and assists: participating in them gradually improves sprint speed, ability range and passive soul income. The item also reduces your weapon damage against NPCs."}],"Restorative Shot":[{"ru":"Помогает восстанавливать здоровье после обменов на линии, если продолжаешь попадать выстрелами: готовая пуля лечит при попадании. Герой даёт больше лечения, чем существо или сфера.","en":"Helps recover health lost in lane trades as long as you keep landing shots: a ready bullet heals on hit. A hero provides more healing than an NPC or orb."}],"Ethereal Shift":[{"ru":"Помогает пережить короткую вражескую связку: мгновенная неуязвимость позволяет переждать её опасную часть. После выхода временные бонусы скорости, спиритической мощи и спиритического сопротивления помогают уйти или вернуться в драку.","en":"Helps you survive a short enemy combo: instant invulnerability lets you wait out its dangerous part. Temporary movement speed, Spirit Power and spirit resistance afterward help you escape or rejoin the fight."}],"Cheat Death":[{"ru":"Когда тебя убивают одной быстрой комбинацией и нужно время, чтобы отойти. После смертельного попадания временная защита от смерти даёт окно для спасения, но твои урон и получаемое лечение в это время снижены.","en":"When a fast combo kills you before you can escape. A lethal hit triggers temporary death immunity, giving you an escape window, but your damage and incoming healing are reduced during it."}],"Mystic Shot":[{"ru":"Добавляет спиритический урон к отдельному выстрелу, усиливая короткие обмены, когда эффект готов. Подходит и для сборки со спиритической мощью, от которой растёт этот урон.","en":"Adds spirit damage to an individual shot, strengthening short trades when the proc is ready. It also fits spirit power builds, which increase that damage."}],"Superior Cooldown":[{"ru":"Улучшай Compress Cooldown, когда тебе нужно чаще применять несколько умений, например чередовать атаку, контроль и защиту в затяжной драке. Сокращение перезарядки всего набора уменьшает ожидание между такими связками.","en":"Upgrade Compress Cooldown when you need several abilities more often, such as alternating damage, control and defense in extended fights. Reducing the cooldowns across your kit shortens the wait between those sequences."}],"Majestic Leap":[{"ru":"Для выхода на высоту, обхода позиции врага или начала атаки сверху. Используй до получения урона от героя: после вражеского попадания предмет некоторое время недоступен.","en":"For reaching high ground, approaching from another angle or starting an attack from above. Use it before taking hero damage, which temporarily prevents activation."}],"Glass Cannon":[{"ru":"Даёт большой прирост урона оружия ценой части максимального здоровья — подходит, если можешь компенсировать уязвимость позицией. Убийства героев накапливают скорострельность, а каждая смерть снимает один накопленный заряд.","en":"Provides a large weapon damage increase at the cost of maximum health, suitable when positioning can compensate for the vulnerability. Hero kills build fire rate stacks, while each death removes one stack."}],"Swift Striker":[{"ru":"Сочетает скорострельность для перестрелок со скоростью спринта для переходов между линиями. Оба бонуса действуют без отдельного срабатывания.","en":"Combines fire rate for gunfights with sprint speed for moving between lanes. Both bonuses work without a separate trigger."}],"Siphon Bullets":[{"ru":"Для затяжной перестрелки с живучей целью: пули временно отнимают у неё максимальное здоровье и передают его тебе. Продолжай попадать, чтобы поддерживать преимущество; после окончания дебаффа украденное здоровье возвращается врагу.","en":"For extended gunfights against a durable target: bullets temporarily steal their maximum health for you. Keep landing shots to maintain the advantage; the stolen health returns when the debuff expires."}],"Healing Rite":[{"ru":"Для восстановления на линии без возвращения на базу — себе или союзнику. Сначала выйди из-под огня: урон от вражеских героев и объектов снимает лечение.","en":"For recovering in lane without returning to base, either on yourself or an ally. Get out of danger first: damage from enemy heroes and objectives removes the healing effect."}],"Debuff Reducer":[{"ru":"Против длительных отрицательных эффектов, из-за которых не удаётся двигаться, применять способности или продолжать атаку. Постоянно сокращает их длительность и не требует отдельного нажатия.","en":"Against long debuffs that stop you moving, casting or continuing an attack. It passively shortens their duration without requiring an active use."}],"Spirit Shredder":[{"ru":"Перед атакой спиритическим уроном пометь цель пулей: это снизит её спиритическое сопротивление и даст тебе и союзникам спиритический вампиризм против неё. Особенно полезен, когда несколько союзников наносят такой урон по одной цели.","en":"Tag a target with a bullet before attacking with spirit damage: this lowers their spirit resistance and grants you and allies spirit lifesteal against them. It is especially useful when several allies focus that target with spirit damage."}],"Hollow Point":[{"ru":"Раскрывается в перестрелках, где удаётся удерживать здоровье выше 65%: тогда получаешь дополнительный урон оружия и снижаешь сопротивление пулям у цели. Восстановление вне боя помогает вернуть нужный запас здоровья перед следующей атакой.","en":"Works best in gunfights where you can stay above 65% health, enabling bonus weapon damage and bullet resistance reduction. Out-of-combat regeneration helps restore that health before the next attack."}],"Headhunter":[{"ru":"Вознаграждает точные попадания героям в голову во время коротких обменов: усиленный выстрел наносит дополнительный урон и лечит. Полученная скорость помогает продолжить атаку или сменить позицию.","en":"Rewards accurate headshots on heroes during short trades: the empowered shot adds damage and heals you. The movement speed it grants helps you continue attacking or reposition."}],"Transcendent Cooldown":[{"ru":"Подходит для сборки, где бой зависит и от умений, и от активных предметов: оба набора эффектов будут раньше готовы к повторной атаке. Улучшай Superior Cooldown, если именно ожидание их восстановления мешает продолжить давление или снова защититься.","en":"Fits builds whose fights depend on both abilities and active items: both sets of effects become ready sooner for another engagement. Upgrade Superior Cooldown when waiting for them prevents you from maintaining pressure or defending again."}],"Blood Tribute":[{"ru":"Обменивает здоровье на скорострельность, скорость передвижения и сопротивление дебаффам для продолжения атаки. Выключай, когда бонусы не используются: расход здоровья идёт всё время работы.","en":"Trades health for fire rate, movement speed and debuff resistance to sustain your attack. Toggle it off when you are not using the bonuses, since it continuously drains health."}],"Dispel Magic":[{"ru":"Когда бой мешают продолжать снимаемые неультимативные дебаффы: очищение также лечит и ускоряет, если удалось что-то снять. Во время оглушения или сна активировать предмет нельзя.","en":"When removable non-ultimate debuffs prevent you from continuing a fight: a successful cleanse also heals and speeds you up. You cannot activate it while stunned or asleep."}],"Knockdown":[{"ru":"Бери, если нужно остановить удалённую или летящую цель и дать команде время на атаку; против цели в воздухе оглушение длится дольше. Применяй заранее: эффект сработает только через 2 секунды.","en":"Buy to stop a distant or airborne target and give your team time to attack; airborne targets suffer a longer stun. Cast ahead of time because the effect takes 2 seconds to arrive."}],"Focus Lens":[{"ru":"Подходит для общей атаки по одному врагу, которому нельзя дать ответить умениями: безмолвие создаёт окно, а часть нанесённого за это время урона повторится после его окончания. Особенно полезен, когда ты и союзники готовы сразу вложить урон в выбранную цель.","en":"Helps focus an enemy who must not answer with abilities: silence creates a window, and a portion of damage dealt during it is applied again when it ends. Especially useful when you and allies are ready to concentrate damage on that target immediately."}],"Weighted Shots":[{"ru":"Для удержания цели под огнём: повторные попадания накапливают замедление и сокращают дистанцию её рывка. Дополнительные урон и сопротивление дебаффам оплачиваются снижением твоей скорости и восстановления выносливости.","en":"Helps keep a target under fire: repeated hits build up a slow and reduce their dash distance. The extra damage and debuff resistance come at the cost of your movement speed and stamina recovery."}],"Infuser":[{"ru":"Для короткого периода сильного спиритического урона, когда нужно одновременно атаковать и лечиться. Включай перед своей комбинацией, чтобы использовать усиленную спиритическую мощь и вампиризм с первых попаданий.","en":"For a short burst of spirit damage when you need to attack and sustain at the same time. Activate before your combo to use the extra Spirit Power and lifesteal from the first hits."}],"Silencer":[{"ru":"Мешает врагу, которому нужны способности для урона или спасения: попадания уменьшают его исходящий спиритический урон и накапливают безмолвие. После окончания безмолвия цель временно невосприимчива к повторному накоплению.","en":"Disrupts an enemy who relies on abilities for damage or escape: bullet hits reduce their outgoing spirit damage and build up silence. After silence ends, the target is temporarily immune to further buildup."}],"Magic Carpet":[{"ru":"Помогает отступить или быстро перелететь в другое место, когда замедления мешают разорвать дистанцию: в полёте они не действуют. Начинай призыв до того, как останешься без времени на спасение: он занимает время, а любое действие во время полёта убирает ковёр.","en":"Helps with retreating or fast travel when slows keep you from opening distance: they do not affect you in flight. Start summoning before you run out of escape time; the summon takes time, and taking any action during flight dismisses the carpet."}],"Disarming Hex":[{"ru":"Улучшай Rusted Barrel, если нужно временно выключить стрельбу опасного врага и пережить его атаку. Снижение сопротивления пулям одновременно помогает тебе и союзникам добить его за время обезоруживания.","en":"Upgrade Rusted Barrel when you need to temporarily stop a dangerous enemy's gunfire and survive their attack. The bullet resistance reduction also helps you and allies finish them during the disarm."}],"Weapon Shielding":[{"ru":"Против быстрого урона оружием: после серии сильных попаданий автоматически даёт барьер и сопротивление пулям. Помогает выдержать продолжение обстрела после срабатывания защиты.","en":"Against bursts of weapon damage: after enough damage arrives in a short period, it automatically grants a barrier and bullet resistance. This helps you survive continued gunfire after it triggers."}],"Tankbuster":[{"ru":"Улучшай Mystic Burst против врагов с большим запасом здоровья, если твои попадания умением превышают порог 165 урона. Заряженное срабатывание добавляет урон от текущего здоровья цели, поэтому особенно полезно в начале атаки по ещё здоровому врагу.","en":"Upgrade Mystic Burst against enemies with large health pools when your ability hits exceed its 165-damage threshold. The charged proc adds damage based on the target's current health, making it especially useful when opening on a healthy enemy."}],"Split Shot":[{"ru":"Против сгруппированных героев включённый мультивыстрел позволяет за одну атаку задеть нескольких и накопить урон оружия. Одна цель получает только одно попадание от каждого мультивыстрела.","en":"Against grouped heroes, activated multishot lets one attack hit several of them and build weapon damage stacks. Each target can only be hit once per multishot."}],"Heroic Aura":[{"ru":"Помогает совместному наступлению: аура защищает ближайших союзных существ от пуль, а активация ускоряет передвижение и стрельбу союзников. Для усиления волны используй рядом с союзными бойцами: они получают удвоенный активный бонус.","en":"Supports a coordinated push: the aura protects nearby friendly units from bullets, while activation boosts allied movement and fire rate. Use it near allied minions to strengthen a wave, since they receive double the active bonus."}],"Counterspell":[{"ru":"Полезен против опасных способностей и активных предметов, если можешь встретить их парированием. Успешная защита даёт лечение, скорость и спиритическую мощь для ответной атаки.","en":"Useful against dangerous abilities and active items when you can time a parry against them. A successful spell parry provides healing, movement speed and Spirit Power for a counterattack."}],"Juggernaut":[{"ru":"Для преследования и выхода из-под огня, когда мешают замедления и атаки вблизи. Повышает скорость и устойчивость к этим угрозам, а у стреляющих по тебе врагов снижает скорострельность.","en":"For chasing or escaping when slows and close-range attacks hold you back. It improves movement and resistance to those threats, while enemies who shoot you suffer reduced fire rate."}],"Long Range":[{"ru":"Поддерживает стрельбу издалека, если удерживаешь врага дальше 15 м: там включается дополнительный урон оружия. Увеличенная дальность падения урона помогает сохранять урон на расстоянии.","en":"Supports distant shooting when you keep enemies beyond 15 m, where the bonus weapon damage activates. Extended damage falloff range helps preserve damage at distance."}],"Lifestrike":[{"ru":"Для затяжной драки вблизи: удары периодически лечат и замедляют врага, помогая продолжать преследование. По героям лечение сильнее, а лёгкие удары запускают более долгую перезарядку эффекта.","en":"For extended close-range fighting: melee hits periodically heal you and slow the enemy to help you keep chasing. Healing is stronger against heroes, and light melee starts a longer effect cooldown."}],"Enchanter's Emblem":[{"ru":"Когда нужна защита от спиритического урона и усиление собственных способностей. Спиритическая мощь и сокращение перезарядок действуют при высоком здоровье, поэтому выгодно начинать бой восстановленным.","en":"When you need spirit resistance as well as stronger abilities. Its Spirit Power and cooldown bonuses require high health, so entering a fight fully recovered makes better use of them."}],"Phantom Strike":[{"ru":"Позволяет сразу добраться до стрелка или героя в воздухе, опустить его на землю и обезоружить. Подходит для начала атаки вблизи; после прыжка ты оказываешься рядом с выбранным врагом.","en":"Lets you reach a gunner or airborne hero, pull them to the ground and disarm them. Useful for starting a close-range attack; the teleport puts you next to the chosen enemy."}],"Armor Piercer":[{"ru":"Против высокого сопротивления пулям даёт шанс игнорировать его отдельными выстрелами. Такие пули также проходят сквозь врагов, помогая поражать цели, стоящие друг за другом.","en":"Against high bullet resistance, it gives individual shots a chance to ignore that resistance. Those bullets also pierce enemies, helping hit targets lined up behind each other."}],"Intensifying Magazine":[{"ru":"Непрерывная стрельба наращивает урон оружия, поэтому предмет полезнее, когда можешь долго держать огонь по цели. Дополнительный боезапас продлевает время использования усиления.","en":"Continuous fire ramps up weapon damage, making the item more useful when you can keep shooting a target. Extra ammo extends the time you can use the buff."}],"Spirit Shielding":[{"ru":"Против серий спиритического урона, когда за первым попаданием сразу следуют другие. Полученный за короткое время урон запускает барьер и дополнительное спиритическое сопротивление.","en":"Against bursts of spirit damage followed quickly by more hits. Taking enough damage in a short period triggers a barrier and additional spirit resistance."}],"Lightning Scroll":[{"ru":"Дополняет атаку отложенным контролем, если твой ульт надёжно наносит урон нужным героям. Оглушение с дополнительным уроном приходит через 3 секунды и срабатывает на каждой цели только один раз за ульт.","en":"Adds delayed control to your attack when your ultimate reliably damages the intended heroes. The stun and bonus damage arrive after 3 seconds and trigger only once per target per ultimate."}],"Metal Skin":[{"ru":"Включай под сильный обстрел, чтобы переждать усиленную стрельбу врага или отступить, пока его пули не наносят урона. Во время действия предмета скорость передвижения и дальность рывков снижаются.","en":"Activate under heavy gunfire to outlast an enemy's shooting buff or retreat while their bullets cannot hurt you. Your movement is slower and your dashes are shorter during the effect."}],"Crushing Fists":[{"ru":"Связывает ближний бой со стрельбой: удары возвращают патроны и накапливают снижение сопротивления пулям, а при максимуме зарядов оглушают цель. Тяжёлый удар даёт сразу два заряда и получает отдельное усиление урона.","en":"Connects melee with shooting: melee hits restore ammo and stack bullet resistance reduction, stunning the target at maximum stacks. Heavy melee applies two stacks and benefits from a separate damage boost."}],"Spirit Resilience":[{"ru":"Если основной урон приходит от способностей и других спиритических эффектов. Защита дополнительно усиливается при низком здоровье, помогая пережить продолжение атаки.","en":"When abilities and other spirit effects deal most of the damage you take. Its resistance increases further at low health, helping you survive the follow-up."}],"Spellslinger":[{"ru":"Частые применения способностей и предметов в бою усиливают стрельбу между ними: накапливаются скорострельность и ускорение перезарядки. Каждое новое применение обновляет длительность усиления.","en":"Frequent ability and item casts in combat strengthen the shooting between them by stacking fire rate and reload speed. Each new cast refreshes the buff duration."}],"Opening Rounds":[{"ru":"Усиливает первые попадания по здоровой цели: дополнительный урон оружия действует, пока у врага больше половины здоровья. Ускоренные пули помогают попадать по движущимся целям.","en":"Strengthens opening shots against healthy targets: the extra weapon damage works while the enemy is above half health. Faster bullets help you hit moving targets."}],"Active Reload":[{"ru":"Сокращает паузу между магазинами, если нажимаешь перезарядку в отмеченное окно: успешное нажатие сразу завершает её. Бонусы скорострельности, вампиризма пулями и передвижения помогают продолжить бой.","en":"Shortens the gap between magazines when you press reload in the highlighted window: a successful input finishes it immediately. Fire rate, bullet lifesteal and movement speed bonuses help you keep fighting."}],"Fury Trance":[{"ru":"Для боя с упором на непрерывную стрельбу: повышает скорострельность и позволяет быстрее двигаться при стрельбе. Сначала примени нужные способности и выбери позицию — во время действия предмета способности недоступны, а выносливость нельзя тратить и восстанавливать.","en":"For a window of uninterrupted shooting: it gives fire rate and lets you move faster while firing. Cast the abilities you need and position first: during the effect you are silenced, and stamina use and regeneration are disabled."}],"Vortex Web":[{"ru":"Готовит врагов под общий урон по области: граната стягивает врагов вместе и накладывает Slowing Hex, мешая уйти с помощью умений и предметов передвижения. Бери, если команда может сразу атаковать собранную группу.","en":"Sets up allied area damage: the grenade pulls enemies together and applies Slowing Hex, hindering escapes through movement abilities and items. Buy when the team can immediately attack the gathered group."}],"Shadow Weave":[{"ru":"Даёт скрытно подойти и открыть бой с усилением скорострельности, спиритической мощи и ближнего боя, когда заканчиваешь невидимость атакой или способностью. При сближении учитывай обнаружение вблизи и краткое раскрытие от входящего урона.","en":"Lets you approach concealed and open with bonus fire rate, spirit power and melee damage when you end stealth with an attack or ability. Account for close-range detection and brief reveals from incoming damage as you approach."}],"Indomitable":[{"ru":"Когда опасен первый же контроль и трудно успеть нажать защитный предмет. Автоматически снимает следующее оглушение, связывание, обездвиживание, сон, безмолвие или страх, затем даёт барьер и сокращает перезарядки способностей.","en":"When the first control effect is dangerous and reacting with an active defense is difficult. It automatically cleanses the next stun, chain, immobilize, sleep, silence or fear, then grants a barrier and reduces ability cooldowns."}],"Melee Lifesteal":[{"ru":"Помогает восстанавливать здоровье в разменах, если удаётся попадать ударами ближнего боя. По героям лечение заметно сильнее, а тяжёлые удары позволяют чаще пользоваться готовым эффектом, чем лёгкие.","en":"Helps you recover health in trades when you can land melee attacks. Healing is much stronger against heroes, and heavy melee lets the effect recover sooner than light melee."}],"Compress Cooldown":[{"ru":"Помогает, когда одно ключевое умение не успевает восстановиться к следующему размену или второй части драки. Усиль его, чтобы чаще получать именно нужный урон, защиту или контроль.","en":"Helps when one key ability is still on cooldown at the next trade or the second part of a fight. Imbue it to gain more frequent access to the damage, protection or control you need most."}],"Escalating Exposure":[{"ru":"Подходит для длительного спиритического урона по одному врагу: повторные попадания накапливают усиление твоего урона по нему. Бери, если можешь поддерживать давление, а не рассчитываешь закончить весь бой одним попаданием.","en":"Fits sustained spirit damage against one enemy: repeated hits build up an amplification of your spirit damage to that target. Buy when you can maintain pressure rather than relying on a single hit to finish the fight."}],"Spiritual Overflow":[{"ru":"Связывает стрельбу со спиритическим уроном: попадания по героям заряжают усиление скорострельности, спиритической мощи и спиритического вампиризма. Набери заряд выстрелами перед применением способностей.","en":"Connects shooting with spirit damage: hits on heroes charge a buff to fire rate, spirit power and spirit lifesteal. Build the charge with shots before casting abilities."}],"Echo Shard":[{"ru":"Полезен, если исход атаки решает повтор одного обычного умения — например, ещё одно попадание или вторая порция контроля. Выбери его для сброса перезарядки: ульт повторить нельзя, а перезарядка самого предмета растёт с перезарядкой выбранного умения.","en":"Useful when repeating one non-ultimate ability decides the attack, such as landing another damaging hit or a second control effect. Imbue it for the reset; ultimates cannot be repeated, and the item's own cooldown increases with the chosen ability's cooldown."}],"Healbane":[{"ru":"Против врагов, которые выживают за счёт лечения и вампиризма: накладывай антихил спиритическим уроном перед их восстановлением и поддерживай его повторными попаданиями. Смерть героя под эффектом дополнительно лечит тебя.","en":"Against enemies who survive through healing and lifesteal: apply healing reduction with spirit damage before they recover and refresh it with further hits. A hero dying under the effect also heals you."}],"Arcane Surge":[{"ru":"Полезен, если перед ключевым умением ты можешь сделать рывок с прыжком: следующее применение получит больше дальности, длительности и спиритической мощи. Подходит для начала атаки с усиленным контролем или уроном; применить умение нужно в течение 7 секунд.","en":"Useful when you can dash-jump before a key ability: the next cast gains range, duration and Spirit Power. It helps open an attack with stronger control or damage; cast the ability within 7 seconds."}],"Improved Spirit":[{"ru":"Улучшай Extra Spirit, если несколько важных умений зависят от спиритической мощи и им не хватает урона или силы эффекта. Восстановление вне боя дополнительно помогает возвращаться к зачистке и разменам после потери здоровья.","en":"Upgrade Extra Spirit when several important abilities scale with Spirit Power and need more damage or effect strength. Out-of-combat regeneration also helps you return to farming and trading after losing health."}],"Healing Booster":[{"ru":"Для сборки, в которой регулярно лечишь себя или союзников способностями и предметами. Усиление лечения делает каждое такое применение полезнее.","en":"For builds that regularly heal yourself or allies with abilities and items. Healing amplification makes each of those uses more effective."}],"Rapid Rounds":[{"ru":"Простое усиление стрельбы, когда можешь держать цель в прицеле: дополнительная скорострельность позволяет выпустить больше пуль за то же время.","en":"A straightforward shooting upgrade when you can keep your aim on target: extra fire rate lets you fire more bullets in the same time."}],"Mystic Regeneration":[{"ru":"Помогает восстанавливаться между разменами на линии, если ты регулярно задеваешь героев спиритическим уроном. Попадания по разным героям накапливают восстановление; урон по бойцам сам по себе его не даёт.","en":"Helps sustain lane trades when you regularly deal spirit damage to heroes and want health back between attacks. Hitting different heroes stacks the regeneration; damaging troopers alone does not grant it."}],"Leech":[{"ru":"Для затяжных боёв против команды с антихилом: даёт вампиризм от пуль и спиритического урона и ослабляет вражеское снижение лечения. Полезен, если можешь продолжать наносить урон и за счёт него восстанавливаться.","en":"For extended fights against a team with healing reduction: it provides bullet and spirit lifesteal and reduces the impact of enemy anti-heal. Useful when you can keep dealing damage and sustain through it."}],"Warp Stone":[{"ru":"Для мгновенной смены позиции: уйти за укрытие, пересечь опасный участок или сократить дистанцию до цели. Временное сопротивление пулям помогает пережить обстрел после перемещения.","en":"For immediate repositioning: reach cover, cross a dangerous gap or close on a target. Temporary bullet resistance helps you survive gunfire after the teleport."}],"Veil Walker":[{"ru":"Для обходов и внезапного появления с фланга: проход через космическую завесу даёт невидимость, лечение и скорость. Прокладывай перемещения через завесы, чтобы регулярно получать эти эффекты.","en":"For rotations and surprise flanks: passing through a cosmic veil grants stealth, healing and movement speed. Route your movement through veils to make regular use of these effects."}],"Cultist Sacrifice":[{"ru":"Позволяет получать дополнительные души и длительное усиление, если регулярно находишь вражеских существ для поглощения. Покупка особенно полезна, когда используешь и дополнительный заряд способности, и увеличенную дальность.","en":"Consuming enemy NPCs provides extra souls and a long-lasting buff, provided you can regularly find targets. The purchase is especially useful when you use both the extra ability charge and increased range."}],"Kinetic Dash":[{"ru":"Используй рывок-прыжок перед стрельбой, чтобы получить скорострельность и временные патроны до следующей перезарядки. Дополнительная выносливость и её восстановление помогают чаще менять позицию.","en":"Dash-jump before shooting to gain fire rate and temporary ammo until your next reload. Extra stamina and stamina recovery help you reposition more often."}],"Weakening Headshot":[{"ru":"Начинай атаку попаданием в голову, чтобы снизить сопротивление пулям и усилить последующую стрельбу по цели.","en":"Open with a headshot to lower bullet resistance and strengthen follow-up fire against the target."}],"Quicksilver Reload":[{"ru":"Подходит для чередования стрельбы с одним удобным умением: когда эффект предмета готов, применение выбранного умения перезарядит оружие и позволит продолжить огонь без обычной паузы. Особенно полезно применять его после расходования магазина, получая заодно дополнительный урон и скорострельность.","en":"Fits alternating gunfire with one convenient ability: when the item effect is ready, casting the imbued ability reloads your weapon so you can keep shooting without a normal reload break. It is especially useful after spending your magazine, adding damage and fire rate as well."}],"Vampiric Burst":[{"ru":"Когда нужно добить цель за одну длинную очередь и восстановиться за счёт стрельбы. Включай, когда уже можешь попадать: временные скорострельность, вампиризм и добавленные патроны работают только в короткое окно усиления.","en":"When you need to finish a target in one sustained burst and heal through shooting. Activate once you can land hits: the temporary fire rate, lifesteal and added ammo give you a short damage window."}],"Healing Nova":[{"ru":"Полезна, когда несколько союзников потеряли здоровье в одном бою или при осаде. Собери их рядом с собой перед активацией, чтобы одно применение восстановило здоровье всей группе.","en":"Useful when several allies lose health during the same fight or siege. Bring them close before activating so a single use heals the group."}],"Colossus":[{"ru":"Для драки вблизи с несколькими противниками: временно усиливает защиту от пуль и спирита, а также ближний бой. Замедление и ослабление рывков врагов рядом помогают удерживать их возле себя.","en":"For close-range fights against several enemies: it temporarily improves bullet and spirit resistance as well as melee damage. Nearby enemies are slowed and have weaker dashes, helping you keep them close."}],"Guardian Ward":[{"ru":"Защищает союзника, которого начинают фокусить, или помогает ему выйти из опасной зоны за счёт барьера и скорости. Применение на союзника сокращает перезарядку по сравнению с применением на себя.","en":"Protects an ally who is being focused or helps them escape danger with a barrier and movement speed. Casting on an ally has a shorter cooldown than self-casting."}],"Mystic Vulnerability":[{"ru":"Подходит для атаки, в которой после первого спиритического попадания ты или союзники продолжаете наносить цели спиритический урон. Снижение спиритического сопротивления усиливает продолжение размена, особенно против врага, которого команда собирается атаковать вместе.","en":"Fits attacks where you or allies keep dealing spirit damage after the opening hit. The spirit resistance reduction strengthens the follow-up, especially against a target the team plans to focus together."}],"Superior Duration":[{"ru":"Улучшай Duration Extender, если длительность важна сразу для нескольких умений и предметов — например, для защитных бонусов и контроля в одной драке. Более долгие эффекты помогают сохранить преимущество на протяжении затяжного размена.","en":"Upgrade Duration Extender when duration matters for several abilities and items, such as defensive buffs and control in the same fight. Longer effects help sustain your advantage through an extended trade."}],"Bullet Resist Shredder":[{"ru":"Подходит для связки «спиритический урон, затем стрельба»: попадание снижает сопротивление цели пулям и помогает тебе и союзникам быстрее её расстрелять. Особенно полезен, если ты легко задеваешь нужного врага умением перед общей атакой.","en":"Fits a spirit-damage opener followed by gunfire: the hit reduces the target's bullet resistance, helping you and allies shoot them down faster. Especially useful when you can reliably tag the intended target with an ability before the team attacks."}],"Suppressor":[{"ru":"Полезен против врагов, которые наносят основной урон стрельбой: твои спиритические попадания будут снижать их скорострельность. Бери, если можешь регулярно задевать опасного стрелка и уменьшать его давление на себя или союзника.","en":"Useful against enemies who deal most of their damage through gunfire: your spirit hits reduce their fire rate. Buy when you can regularly tag a dangerous shooter and ease their pressure on you or an ally."}],"Spirit Rend":[{"ru":"Помогает сосредоточить спиритический урон на одной цели: пули снижают её спиритическое сопротивление и дают тебе и союзникам спиритический вампиризм против неё. Повторные попадания в голову дополнительно накапливают снижение этого сопротивления.","en":"Helps focus spirit damage on one target: bullets lower their spirit resistance and grant you and allies spirit lifesteal against them. Repeated headshots stack additional spirit resistance reduction."}],"Divine Barrier":[{"ru":"Для спасения союзника, которому мешают уйти дебаффы: снимает эффекты, кроме оглушения, и даёт барьер со скоростью. Можно использовать на себя; на союзнике предмет перезаряжается быстрее.","en":"For saving an ally whose escape is hindered by debuffs: it removes non-stun debuffs and grants a barrier plus movement speed. You can self-cast, but casting on an ally gives a shorter cooldown."}],"Golden Goose Egg":[{"ru":"Бери, если можешь некоторое время развивать экономику с пониженным уроном: ценность яйца растёт, а при вылуплении ты получаешь души и постоянные бонусы. При необходимости немедленно драться штраф к урону делает такую покупку менее полезной.","en":"Buy when you can spend time building your economy with reduced damage: the egg gains value, then hatching grants souls and permanent buffs. The damage penalty makes it less useful when you need immediate fighting strength."}],"Cold Front":[{"ru":"Помогает, когда в ближней драке враг уходит из-под твоей атаки или преследует тебя: ледяная волна наносит урон и сильно замедляет попавшие под неё цели. Радиус вокруг тебя позволяет заодно задеть нескольких врагов или добить группу бойцов.","en":"Helps when an enemy pulls out of your close-range attacks or chases you: the ice blast damages and heavily slows targets it hits. Its area around you can also catch several enemies or finish a group of troopers."}],"Unstoppable":[{"ru":"Для входа в бой или применения важной способности, которую враги могут сорвать контролем. Включай заранее: во время оглушения или сна предмет уже нельзя нажать.","en":"For entering a fight or using an important ability that enemies could interrupt with crowd control. Activate beforehand: you cannot use the item once stunned or asleep."}],"Recharging Rush":[{"ru":"Продлевает комбинацию героя со способностями на зарядах: достаточный урон оружием за короткое время возвращает по заряду каждой такой способности. Полезен, если можешь быстро набрать нужный порог попаданиями.","en":"Extends a combo for a hero with charged abilities: enough weapon damage within a short window restores a charge to each of those abilities. It helps when you can quickly reach the required damage threshold."}],"Spellbreaker":[{"ru":"Против сильных отдельных попаданий спиритическим уроном, которые снимают большую часть здоровья за раз. Готовый защитный эффект уменьшает следующее такое попадание, дополняя постоянное спиритическое сопротивление.","en":"Against large individual spirit hits that take a substantial chunk of health at once. The ready defensive effect reduces the next qualifying hit, on top of its permanent spirit resistance."}],"Extra Charge":[{"ru":"Полезен, если у твоего умения есть заряды и одного применения не хватает для добивания, зачистки или повторной попытки попадания. Дополнительный заряд даёт запас применений, а спиритическая мощь усиливает именно умения с зарядами.","en":"Useful when an ability uses charges and one cast is not enough to finish a target, clear a wave or try again after a miss. The extra charge adds a reserve cast, while its Spirit Power bonus applies specifically to charged abilities."}],"Spirit Snatch":[{"ru":"Улучшай Spirit Strike для ближних разменов с героем, который зависит от спиритической мощи: удар крадёт его мощь и спиритическое сопротивление, одновременно усиливая тебя. Тяжёлый удар даёт полный эффект, а у лёгкого он слабее на 30%.","en":"Upgrade Spirit Strike for close-range trades against a hero who relies on Spirit Power: the melee hit steals their power and spirit resistance while strengthening you. Heavy melee gives the full effect; light melee effects are 30% weaker."}],"Sharpshooter":[{"ru":"Для атак дальше 15 м даёт дополнительный урон, увеличение прицела и скорость пуль. Обычная скорость передвижения снижается, поэтому позицию лучше занять до перестрелки.","en":"For attacks beyond 15 m, it provides bonus damage, stronger zoom and faster bullets. Your normal movement speed falls, so establish your position before trading shots."}],"Silence Wave":[{"ru":"Бери, если враги успевают ответить защитным умением или уйти после твоего нападения: волна безмолвия даёт окно для атаки, особенно по нескольким стоящим рядом целям. Попадай до применения опасного умения — уже начавшееся поддерживаемое умение безмолвие не прервёт.","en":"Buy when enemies answer your initiation with a defensive ability or an escape: the silence wave creates an attack window, especially against several nearby targets. Land it before the dangerous cast; silence will not interrupt an ability already being channeled."}],"Plated Armor":[{"ru":"Против стрелков, особенно если их пули накладывают опасные эффекты. Предмет даёт шанс предотвратить урон входящей пули либо её эффекты попадания, помогая выдерживать продолжительный обстрел.","en":"Against gun builds, especially those with dangerous bullet on-hit effects. The item gives a chance to prevent an incoming bullet's damage or its on-hit effects, helping you withstand sustained fire."}],"Capacitor":[{"ru":"Против врага, который уходит рывками или умениями передвижения, активный снаряд даёт замедление и блокирует расход выносливости и средства передвижения. Цепные разряды также усиливают стрельбу по сгруппированным врагам.","en":"Against enemies who escape through dashes or movement abilities, the active projectile slows them and blocks stamina use and movement tools. Chain shocks also strengthen your fire against grouped enemies."}],"Mystic Reverb":[{"ru":"Бери, если одно выбранное умение наносит большой урон и ты часто попадаешь по врагу рядом с его союзниками: отложенный повтор урона накажет их за тесную позицию. Замедление помогает продолжить атаку, а вампиризм выбранного умения поддерживает тебя в размене.","en":"Buy when one imbued ability deals heavy damage and often hits an enemy near their allies: the delayed damage echo punishes that grouping. Its slow helps you follow up, while the imbued ability's lifesteal sustains the trade."}],"Spirit Strike":[{"ru":"Подходит для размена, который ты начинаешь ударом по герою и продолжаешь спиритическим уроном: удар добавит урон и снизит сопротивление цели перед продолжением атаки. Лёгкий удар тоже запускает эффект, но его перезарядка будет вдвое дольше.","en":"Fits trades that start with a melee hit on a hero and continue with spirit damage: the hit adds damage and lowers their resistance for the follow-up. Light melee also triggers it, but the cooldown is twice as long."}],"Grit":[{"ru":"Ранний защитный предмет для короткого опасного размена. Включай барьер перед ожидаемым попаданием или комбинацией, чтобы сохранить здоровье для ответной атаки.","en":"An early defensive option for a dangerous short trade. Activate the barrier before an expected hit or combo to preserve health for your counterattack."}],"Reactive Barrier":[{"ru":"Против комбинаций, где за контролем сразу идёт основной урон. После оглушения, связывания, обездвиживания, сна или безмолвия автоматически появляется барьер, который помогает пережить продолжение атаки.","en":"Against combos that follow crowd control with their main damage. A stun, chain, immobilize, sleep or silence automatically triggers a barrier to help you survive the follow-up."}],"Cursed Relic":[{"ru":"Бери, чтобы прервать решающее действие врага и на короткое время лишить его умений, стрельбы и предметов; снятие бонусов, не относящихся к ульту, дополнительно ослабляет цель. Лучше использовать при готовой поддержке союзников: твой собственный урон на время эффекта снижается.","en":"Buy to interrupt a decisive enemy action and briefly deny their abilities, gunfire and items; removing non-ultimate buffs further weakens the target. Use it with allies ready to follow up, since your own damage is reduced for the effect's duration."}],"Inhibitor":[{"ru":"Против сильного источника урона, который ещё и много лечится: попадания пулями накапливают ослабление его урона и лечения. Сосредоточь огонь на опасной цели, чтобы наложить оба эффекта.","en":"Useful against a major damage threat who also heals heavily: bullet hits build up damage suppression and healing reduction. Focus your shots on that threat to apply both effects."}],"Stalker":[{"ru":"Облегчает преследование: урон оружием в пределах 8 м открывает рану, снижает сопротивление пулям и раскрывает цель за стенами. Полученная скорость помогает не отпускать раненого врага.","en":"Helps pursuit: weapon damage within 8 m opens a wound, lowers bullet resistance and reveals the target through walls. The movement speed you gain helps you keep up with the wounded enemy."}],"Diviner's Kevlar":[{"ru":"Если после применения ультимейта нужно выдержать ответный урон и продолжить бой способностями. Барьер и временная спиритическая мощь появляются именно при использовании ультимейта, поэтому связывай вход в бой с его готовностью.","en":"When you need to survive retaliation after using your ultimate and keep fighting with abilities. The barrier and temporary Spirit Power trigger on casting your ultimate, so time your engagement around its availability."}],"Express Shot":[{"ru":"Усиливает отдельную атаку при выходе на цель: готовый эффект выпускает два выстрела подряд с повышенными уроном и скоростью пуль. Перед атакой оставляй патроны на дополнительный расход.","en":"Strengthens an opening attack: the ready proc fires twice in quick succession with increased damage and bullet velocity. Keep enough ammo for the extra cost before attacking."}],"Fortitude":[{"ru":"Позволяет восстанавливать большой запас здоровья между стычками без возвращения на базу. Нужна пауза без полученного урона; при высоком здоровье предмет также ускоряет передвижение.","en":"Lets you recover a large health pool between skirmishes without returning to base. You need a break from incoming damage; at high health it also increases movement speed."}],"Bullet Lifesteal":[{"ru":"Для героя, который восстанавливается прямо во время перестрелки за счёт попаданий пулями. Особенно полезен в долгих разменах, где есть возможность продолжать стрелять по цели.","en":"For a hero who can recover during gunfights by landing bullet damage. Most useful in extended trades where you can keep shooting your target."}],"Headshot Booster":[{"ru":"Усиливает короткий обмен выстрелами, если регулярно попадаешь героям в голову: готовый эффект добавляет урон к точному попаданию.","en":"Strengthens a short trade when you regularly headshot heroes: the ready proc adds damage to a well-placed shot."}],"Surge of Power":[{"ru":"Подходит для преследования со стрельбой после одного часто используемого умения, которое ты хочешь усилить. Его применение даёт скорость передвижения и позволяет двигаться с полной скоростью во время атаки, помогая сохранять дистанцию до врага.","en":"Buy to strengthen one frequently used ability and follow it by chasing with gunfire. Casting it grants movement speed and lets you move at full speed while attacking, helping you keep the enemy within reach."}],"Slowing Bullets":[{"ru":"Чтобы врагу было труднее выйти из-под огня, накапливай замедление повторными попаданиями. Эффект также сокращает дистанцию его рывка.","en":"Repeated bullet hits build up a slow, making it harder for an enemy to leave your firing line. The effect also reduces their dash distance."}],"Burst Fire":[{"ru":"Позволяет развить первое попадание по герою в короткую усиленную атаку: бонусы скорострельности и передвижения помогают продолжать огонь и двигаться вместе с целью.","en":"Turns your first bullet hit on a hero into a short window of stronger fire: bonus fire rate and movement speed help you keep attacking and keep pace with the target."}],"Spirit Lifesteal":[{"ru":"Для восстановления во время боя, если регулярно наносишь спиритический урон. Хорошо работает в затяжной атаке, где способности и другие спиритические эффекты продолжают попадать по врагу.","en":"For sustain during a fight when you regularly deal spirit damage. Useful in prolonged engagements where your abilities and other spirit effects keep hitting the enemy."}],"Toxic Bullets":[{"ru":"Против большого запаса здоровья или сильного лечения помогает кровотечение, которое наносит урон от максимального здоровья и снижает входящее лечение. Для его наложения нужно накопить эффект попаданиями пуль.","en":"Against high health pools or strong healing, the bleed deals maximum-health damage and reduces incoming healing. You must first build up the effect with bullet hits."}],"Frenzy":[{"ru":"Помогает продолжить бой после падения ниже половины здоровья: срабатывание даёт скорострельность, скорость передвижения и сокращает уже действующие дебаффы. Наибольшую пользу получаешь, если в этот момент ещё можешь стрелять.","en":"Helps you keep fighting after dropping below half health: the trigger grants fire rate and movement speed and reduces existing debuffs. You get the most from it when you can still shoot at that point."}],"Torment Pulse":[{"ru":"Добавляет урон в затяжной ближней драке: автоматические импульсы добавляют спиритический урон, пока ты дерёшься вблизи. За раз они поражают только двух ближайших врагов, поэтому в толпе урон может уйти не в нужного героя.","en":"Adds damage when you spend extended time close to enemies: automatic pulses add spirit damage while you fight at close range. Each pulse hits only the two nearest enemies, so a crowd can divert damage away from your intended hero."}],"Refresher":[{"ru":"Бери, когда повторное применение решающих умений, включая ульт, может выиграть одну важную драку. Используй после расходования нужных умений и зарядов, чтобы получить второй набор применений; долгая перезарядка предмета требует выбирать момент.","en":"Buy when casting decisive abilities, including your ultimate, again can win an important fight. Use it after spending the abilities and charges you need to gain a second set of casts; the item's long cooldown makes the timing matter."}],"Ricochet":[{"ru":"Распространяет стрельбу на соседние цели, если враги стоят рядом. Особенно полезен с уже купленными эффектами попадания пулями: рикошеты накладывают их на дополнительные цели.","en":"Spreads your fire to nearby targets when enemies stand together. It is especially useful with bullet procs you already own, since ricochets apply them to additional targets."}],"Monster Rounds":[{"ru":"Ускоряет зачистку бойцов и нейтральных лагерей за счёт дополнительного урона по существам. Сопротивление их пулям уменьшает потерю здоровья во время фарма.","en":"Extra damage against NPCs speeds up clearing troopers and neutral camps. Resistance to their bullets reduces the health you lose while farming."}],"Mystic Expansion":[{"ru":"Помогает, когда одно ключевое умение регулярно не достаёт до цели или краем области не задевает соседних врагов. Усиль именно его, чтобы безопаснее начинать размен или попадать по группе.","en":"Helps when one key ability repeatedly falls short of its target or narrowly misses nearby enemies with its area. Imbue that ability to start trades from safer range or catch a group."}],"Lucky Shot":[{"ru":"При большом числе попаданий даёт дополнительные срабатывания урона оружия, а увеличенный магазин продлевает огонь. Дополнительный урон Lucky Shot не может быть критическим.","en":"Landing many hits gives you more chances to proc bonus weapon damage, while the larger magazine extends your fire. Lucky Shot's bonus damage cannot crit."}],"Titanic Magazine":[{"ru":"Когда частые перезарядки прерывают урон по цели или объекту, большой прирост боезапаса продлевает огонь. Дополнительный урон оружия усиливает эту стрельбу.","en":"When frequent reloads interrupt damage against a target or objective, the large ammo increase extends your fire. Extra weapon damage strengthens that shooting."}],"Mercurial Magnum":[{"ru":"Улучшай Quicksilver Reload, если после выбранного умения ты продолжаешь много стрелять и при этом набираешь спиритическую мощь. Когда эффект предмета готов, применение этого умения перезаряжает оружие, а до следующей перезарядки пули получают дополнительный спиритический урон, растущий от этой мощи.","en":"Upgrade Quicksilver Reload when you keep firing after the imbued ability and also build Spirit Power. When the item effect is ready, casting that ability reloads your weapon, then your bullets gain bonus spirit damage scaling with that power until your next reload."}],"Extra Spirit":[{"ru":"Подходит для умений, у которых урон, лечение или другой нужный эффект растёт от спиритической мощи. Помогает усилить сразу несколько таких умений, если проблема в их силе, а не в дальности или перезарядке.","en":"Fits abilities whose damage, healing or another useful effect scales with Spirit Power. It strengthens several such abilities at once when their output is the problem, rather than their reach or cooldown."}],"Hunter's Aura":[{"ru":"В дуэли на дистанции до 15 м особенно ценна: снижение сопротивления пулям и скорострельности удваивается, если рядом только один вражеский герой. При нескольких врагах аура продолжает ослаблять всех в радиусе, но без удвоения.","en":"Especially useful in a duel within 15 m: its bullet resistance and fire rate reductions double when only one enemy hero is nearby. With several enemies, the aura still weakens those in range, without the doubled effect."}],"Scourge":[{"ru":"Полезен, если ты или союзник долго сражаетесь вплотную к врагам с большим запасом здоровья: аура наносит урон от их максимального здоровья. Наложи на того, кто останется в центре драки, чтобы одновременно дать ему спиритическое сопротивление и сопротивление дебаффам и сократить уже действующие дебаффы.","en":"Useful when you or an ally stay close to enemies with large health pools: the aura deals damage based on their maximum health. Cast it on whoever will remain in the fight to also grant spirit and debuff resistance and shorten existing debuffs."}],"Sprint Boots":[{"ru":"Удобны для частых переходов между линиями и лагерями: скорость бега сокращает время в пути, а восстановление вне боя помогает вернуться к следующему размену с большим запасом здоровья.","en":"Useful for frequent rotations between lanes and camps: sprint speed reduces travel time, while out-of-combat regeneration helps you enter the next trade with more health."}],"Bullet Resilience":[{"ru":"Против стрелков, которые быстро снимают здоровье обычными попаданиями. Постоянное сопротивление пулям становится ещё выше при низком здоровье.","en":"Against gun builds that quickly wear you down with bullet hits. Its permanent bullet resistance increases further at low health."}],"Radiant Regeneration":[{"ru":"Поддерживает тебя в затяжной драке с частым применением умений: срабатывания лечения и скорости помогают пережить размен и сменить позицию. Спиритические попадания по героям дополнительно дают восстановление, которое накапливается от разных целей.","en":"Helps you stay in extended fights when you cast abilities regularly: healing and movement-speed procs help you survive trades and reposition. Spirit hits on heroes also grant regeneration that stacks across different targets."}],"Mystic Slow":[{"ru":"Бери, если враги выходят из зоны твоих умений или отрываются после попадания: спиритический урон будет замедлять их и ослаблять наземные рывки. Особенно полезен при повторных попаданиях, которые помогают удерживать цель рядом для продолжения атаки.","en":"Buy when enemies leave your ability areas or pull away after a hit: your spirit damage slows them and weakens ground dashes. Repeated hits are especially useful for keeping the target close enough to continue attacking."}],"Witchmail":[{"ru":"Против крупных попаданий спиритическим уроном, если сам часто используешь способности. Такие попадания сокращают перезарядку случайной способности, позволяя чаще отвечать на вражеские атаки.","en":"Against heavy spirit hits when you also rely on frequent ability use. Those hits reduce a random ability cooldown, letting you respond to enemy attacks more often."}],"Extended Magazine":[{"ru":"Когда патроны заканчиваются раньше, чем удаётся добить цель или зачистить волну, дополнительный боезапас продлевает стрельбу без перезарядки.","en":"Extra ammo keeps you firing when the magazine would otherwise run dry before you finish a target or clear a wave."}],"Rusted Barrel":[{"ru":"Помогает в размене с врагом, который много стреляет: снижение скорострельности уменьшит давление, а снижение сопротивления пулям усилит ответный огонь. Применяй в начале перестрелки по той цели, по которой будете стрелять ты и союзники.","en":"Helps trade with an enemy who relies on gunfire: reducing their fire rate eases the pressure, while reducing their bullet resistance strengthens return fire. Apply it at the start of the shootout to the enemy you and allies intend to shoot."}],"Escalating Resilience":[{"ru":"В продолжительных перестрелках попадания по героям постепенно повышают сопротивление пулям. Увеличенный магазин помогает продолжать огонь и набирать защиту.","en":"In extended gunfights, hits on heroes progressively build bullet resistance. The larger magazine helps you keep firing and stacking protection."}],"Mystic Burst":[{"ru":"Подходит для отдельных сильных попаданий умением, наносящих больше 80 урона: заряженный эффект добавит урон к такому размену. Удобен, когда между атаками есть время на зарядку, а цель нужно добить за короткую связку.","en":"Buy for individual ability hits dealing more than 80 damage: the charged effect adds damage to that trade. It fits attacks spaced far enough apart to recharge, especially when you need to finish a target with a short combo."}],"Restorative Locket":[{"ru":"В боях с частым применением вражеских способностей быстро набирает заряды для лечения. Потрать их, когда одновременно нужны здоровье и выносливость для продолжения боя или отхода.","en":"Fights with frequent nearby enemy casts build healing stacks quickly. Spend them when you need both health and stamina to continue fighting or retreat."}],"Rapid Recharge":[{"ru":"Улучшай Extra Charge, если в затяжной драке постоянно заканчиваются заряды основного умения. Дополнительные заряды, более быстрое восстановление и меньшая пауза между применениями помогают провести несколько атак подряд и раньше подготовить следующие.","en":"Upgrade Extra Charge when your main charged ability keeps running dry in extended fights. More charges, faster recharge and a shorter delay between casts let you chain attacks and prepare the next ones sooner."}],"Tesla Bullets":[{"ru":"При стрельбе по скоплению врагов электрические разряды перескакивают на соседние цели. Помогает зачищать группы, продолжая атаковать одну цель.","en":"When you shoot into a group, shocks jump to nearby enemies. This helps clear clustered targets while you keep firing at one of them."}],"Extra Stamina":[{"ru":"Если на линии не хватает ещё одного рывка, чтобы уйти от атаки или закончить погоню. Дополнительная выносливость и более быстрое восстановление позволяют чаще уклоняться и менять позицию.","en":"When one more dash would let you avoid an attack or finish a chase in lane. Extra stamina and faster recovery let you dodge and reposition more often."}],"Spirit Sap":[{"ru":"Полезен против врага, чьи умения зависят от спиритической мощи: снижение мощи ослабляет их, а снижение сопротивления делает твою спиритическую атаку опаснее. Применяй перед разменом по цели, которая собирается ответить умениями.","en":"Useful against an enemy whose abilities scale with Spirit Power: reducing that power weakens their output, while lowering their resistance strengthens your spirit damage. Apply it before trading with a target about to answer with abilities."}],"Battle Vest":[{"ru":"Для перестрелок, в которых можешь удерживать здоровье выше порога: вместе с защитой от пуль получаешь урон оружия и скорострельность. Восстановись перед новой атакой, чтобы наступательные бонусы снова работали.","en":"For gunfights where you can keep your health above the threshold: alongside bullet resistance, you gain weapon damage and fire rate. Recover before re-engaging to restore the offensive bonuses."}],"Decay":[{"ru":"Бери против цели с большим текущим здоровьем и сильным лечением: постепенный урон ослабляет её перед основной атакой, а снижение лечения мешает восстановиться. Нужен другой источник урона для добивания: Decay не убивает и не вызывает срабатывания предметов.","en":"Buy against a healthy target with strong healing: the damage over time softens them up, while healing reduction limits their recovery. Bring another damage source to finish them; Decay is non-lethal and does not trigger item procs."}],"Point Blank":[{"ru":"На дистанции до 15 м помогает удержать врага рядом: даёт урон оружия и замедление от пуль. Дополнительное здоровье и сопротивление ближнему бою помогают выдержать ответную атаку.","en":"Within 15 m, it helps keep the enemy close through bonus weapon damage and slowing bullets. Extra health and melee resistance help you withstand retaliation."}],"Ballistic Enchantment":[{"ru":"Усиль способность, которой можешь задеть нескольких героев перед стрельбой: увеличенная дальность помогает попасть, а каждый уникальный герой даёт урон оружия. Так попадания способностью подготавливают последующую атаку оружием.","en":"Imbue an ability that can hit several heroes before you shoot: extra range helps it connect, and each unique hero grants weapon damage. Ability hits then set up your follow-up gunfire."}],"Enduring Speed":[{"ru":"Против замедлений, которые мешают догнать врага или выйти из-под огня. Даёт постоянную скорость передвижения и ослабляет влияние вражеских замедлений.","en":"Against slows that keep you from catching an enemy or escaping gunfire. It gives permanent movement speed and reduces the impact of enemy movement slows."}],"Extra Regen":[{"ru":"На линии против частых небольших потерь здоровья, которые постепенно вынуждают отступать. Постоянное восстановление помогает между разменами, а дополнительная часть регенерации работает вне боя.","en":"In lane against repeated chip damage that gradually forces you back. Passive regeneration helps between trades, with an additional regeneration bonus while out of combat."}],"Boundless Spirit":[{"ru":"Развивает Improved Spirit для сборки, где несколько важных умений хорошо растут от спиритической мощи и ты уже набираешь её другими источниками. Предмет даёт и плоскую мощь, и процентный бонус, поэтому усиливает весь такой набор умений.","en":"Upgrade Improved Spirit when several important abilities scale well with Spirit Power and you are already building it from other sources. The item supplies both flat power and a percentage bonus, strengthening that whole set of abilities."}],"Close Quarters":[{"ru":"Усиливает перестрелки в пределах 15 м дополнительным уроном оружия. Сопротивление ближнему бою помогает выдержать ответные удары на этой дистанции.","en":"Adds weapon damage to gunfights within 15 m. Melee resistance helps you withstand retaliatory punches at that distance."}],"Slowing Hex":[{"ru":"Бери против врага, который спасается умением или предметом передвижения: проклятие временно блокирует такие способы ухода и замедляет цель. Накладывай перед атакой; обычное использование выносливости оно не запрещает.","en":"Buy against enemies who escape with movement abilities or items: the hex temporarily blocks those escape tools and slows the target. Apply it before committing to the attack; it does not prevent normal stamina use."}],"Stamina Mastery":[{"ru":"Для погони, отхода и перемещения по высоте, когда обычного запаса выносливости мало. Дополнительное действие в воздухе и увеличенная дальность воздушных прыжков и рывков дают больше вариантов маршрута.","en":"For chasing, escaping and navigating vertical terrain when your normal stamina is not enough. An extra aerial action and longer air jumps and dashes open up more routes."}],"Duration Extender":[{"ru":"Бери, если одно выбранное умение должно дольше удерживать врага, защищать союзника или наносить постепенный урон. Дополнительная длительность полезна, когда цель остаётся под эффектом и ты успеваешь использовать добавленное время.","en":"Buy when one imbued ability needs to hold an enemy, protect an ally or deal damage over time for longer. The extra duration pays off when the target remains affected and you can use the additional time."}],"Spirit Burn":[{"ru":"Бери против сильного лечения, если можешь нанести одной цели 500 спиритического урона за 5 секунд: горение добавит постепенный урон и резко снизит получаемое лечение. Урон по области полезен для запуска горения на нескольких врагах, поскольку перезарядка отдельная для каждой цели.","en":"Buy against strong healing when you can deal 500 spirit damage to one target within 5 seconds: the burn adds damage over time and sharply reduces incoming healing. Area damage helps trigger burns on several enemies because each target has a separate cooldown."}],"Extra Health":[{"ru":"Ранняя покупка, когда не хватает запаса здоровья, чтобы пережить размен или комбинацию врага. Полезна независимо от того, каким типом урона тебя атакуют.","en":"An early purchase when you need more health to survive a trade or an enemy combo. The extra health helps regardless of the damage type you are facing."}],"Melee Charge":[{"ru":"Для атаки через тяжёлые удары увеличивает дальность сближения и усиливает следующий удар, когда эффект готов.","en":"For attacks built around heavy melee, it extends your reach and strengthens the next hit when the proc is ready."}],"Healing Tempo":[{"ru":"Для героя, который часто лечит себя или союзников: лечение дополнительно усиливает скорострельность и передвижение получателя. Обычная регенерация и пассивный вампиризм этот бонус не запускают.","en":"For a hero who frequently heals yourself or allies: healing also buffs the recipient's fire rate and movement speed. Innate regeneration and passive lifesteal do not trigger this bonus."}],"Berserker":[{"ru":"В затяжной перестрелке превращает полученный урон в усиление оружия. Подходит, если выдерживаешь входящий урон и продолжаешь стрелять.","en":"Turns damage taken into bonus weapon damage during an extended gunfight. It suits fights where you can withstand incoming damage and keep firing."}]}
""")!;
}
